def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiouAEIOU'
    result = []

    for char in message:
        # Swap case
        if char.islower():
            swapped = char.upper()
        else:
            swapped = char.lower()

        # If it's a vowel, replace with the letter 2 places ahead
        if char in vowels:
            if char.lower() == 'a':
                new_char = 'c'
            elif char.lower() == 'e':
                new_char = 'g'
            elif char.lower() == 'i':
                new_char = 'k'
            elif char.lower() == 'o':
                new_char = 'q'
            elif char.lower() == 'u':
                new_char = 'w'
            # Handle uppercase vowels by converting to lowercase first, then mapping
            elif char in 'AEIOU':
                if char == 'A':
                    new_char = 'C'
                elif char == 'E':
                    new_char = 'G'
                elif char == 'I':
                    new_char = 'K'
                elif char == 'O':
                    new_char = 'Q'
                elif char == 'U':
                    new_char = 'W'
            result.append(new_char)
        else:
            result.append(swapped)

    return ''.join(result)
