def flip_case(string: str) -> str:
    result = []
    for char in string:
        if char.isupper():
            result.append(char.lower())
        elif char.islower():
            result.append(char.upper())
        else:
            result.append(char)
    return ''.join(result)

def check(flip_case):
    assert flip_case('Hello') == 'hELLO'
check(flip_case)
