```python
def correct_bracketing(brackets: str) -> bool:
    depth = 0
    for b in brackets:
        if b == ">":
            depth += 1
        else:
            depth -= 1
        if depth < 0:
            return False
    return depth == 0
```

```python
def fibfib(n: int):
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 2
    return fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)

def check(fibfib):
    assert fibfib(1) == 0
    assert fibfib(5) == 4
    assert fibfib(8) == 24
check(fibfib)
```

