def search(lst):
    if not lst:
        return -1

    max_val = max(lst)
    frq = [0] * (max_val + 1)

    for i in lst:
        frq[i] += 1

    ans = -1
    for i in range(1, len(frq)):
        if frq[i] >= i:
            ans = i

    return ans

def check(search):
    # manually generated tests
    assert search([4, 1, 2, 2, 3, 1]) == 2
    assert search([1, 2, 2, 3, 3, 3, 4, 4, 4]) == 3
    assert search([5, 5, 4, 4, 4]) == -1
check(search)
```

